content.solution_code:
class Spacecraft {
  #fuelLevel; // Private field declaration
  static MAX_FUEL = 100;
  static LAUNCH_COST = 20;

  constructor(initialFuel) {
    this.#fuelLevel = Math.min(initialFuel, Spacecraft.MAX_FUEL);
  }

  getFuelLevel() {
    return this.#fuelLevel;
  }

  refuel(amount) {
    if (amount <= 0) {
      return "Refuel amount must be positive.";
    }
    const newFuel = this.#fuelLevel + amount;
    this.#fuelLevel = Math.min(newFuel, Spacecraft.MAX_FUEL);
    return `Refueled by ${amount} units. Current fuel: ${this.#fuelLevel}`;
  }

  launch() {
    if (this.#fuelLevel >= Spacecraft.LAUNCH_COST) {
      this.#fuelLevel -= Spacecraft.LAUNCH_COST;
      return `Launch successful! Fuel remaining: ${this.#fuelLevel}`;
    } else {
      return `Launch failed! Not enough fuel. Requires ${Spacecraft.LAUNCH_COST}, has ${this.#fuelLevel}.`;
    }
  }
}

// Example Usage:
const voyager = new Spacecraft(40);
console.log(`Voyager initial fuel: ${voyager.getFuelLevel()}`);
console.log(voyager.refuel(30));
console.log(voyager.launch());
console.log(voyager.launch());
console.log(voyager.refuel(60)); // Should cap at 100
console.log(`Voyager current fuel: ${voyager.getFuelLevel()}`);
console.log(voyager.launch());
console.log(voyager.launch());
console.log(voyager.launch()); // Should fail

